function(container, apiUrl, tables) {
  // 初期化処理
  const storeSelect = container.querySelector('#store-select');
  const categoryCheckboxes = container.querySelector('#category-checkboxes');
  const progressContainer = container.querySelector('#progress-container');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressStatus = container.querySelector('#progress-status');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const successMessage = container.querySelector('#success-message');
  const successText = container.querySelector('#success-text');

  // 今日の日付を設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const oneYearAgo = new Date(today);
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = new Date(tomorrow.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = oneYearAgo.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み（商品マスタから商品カテゴリIDを抽出）
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      const categoryIds = [...new Set(products.map(p => p.商品カテゴリID))];
      categoryIds.forEach((categoryId, index) => {
        const label = document.createElement('label');
        label.style.display = 'flex';
        label.style.alignItems = 'center';
        label.style.marginBottom = '8px';
        label.style.color = 'var(--text)';

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = categoryId;
        checkbox.style.marginRight = '8px';

        label.appendChild(checkbox);
        label.appendChild(document.createTextNode(`カテゴリ ${index + 1}`));
        categoryCheckboxes.appendChild(label);
      });
    }
  }

  // 季節要因スライダーの値更新
  ['spring', 'summer', 'autumn', 'winter'].forEach(season => {
    const slider = container.querySelector(`#${season}-factor`);
    const valueSpan = container.querySelector(`#${season}-value`);
    slider.addEventListener('input', () => {
      valueSpan.textContent = slider.value;
    });
  });

  // エラー表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.classList.remove('hidden');
    successMessage.classList.add('hidden');
  }

  // 成功表示関数
  function showSuccess(message) {
    successText.textContent = message;
    successMessage.classList.remove('hidden');
    errorMessage.classList.add('hidden');
  }

  // エラー・成功メッセージを隠す
  function hideMessages() {
    errorMessage.classList.add('hidden');
    successMessage.classList.add('hidden');
  }

  // 進捗バー更新
  function updateProgress(percent, status) {
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}%`;
    progressStatus.textContent = status;
  }

  // バリデーション関数
  function validateForm() {
    hideMessages();

    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    const storeId = storeSelect.value;
    const selectedCategories = Array.from(categoryCheckboxes.querySelectorAll('input[type="checkbox"]:checked'));
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    const accuracyThreshold = parseInt(container.querySelector('#accuracy-threshold').value);

    // 予測対象期間チェック
    if (!startDate || !endDate) {
      showError('予測対象期間を設定してください。');
      return false;
    }

    const today = new Date().toISOString().split('T')[0];
    if (startDate <= today) {
      showError('予測対象期間に過去の日付は選択できません。');
      return false;
    }

    if (startDate >= endDate) {
      showError('予測対象期間の終了日は開始日より後の日付を選択してください。');
      return false;
    }

    // 店舗選択チェック
    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }

    // 商品カテゴリ選択チェック
    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください。');
      return false;
    }

    // 予測モデル選択チェック
    if (!selectedModel) {
      showError('予測モデルを選択してください。');
      return false;
    }

    // 学習データ期間チェック
    if (!learningStart || !learningEnd) {
      showError('学習データ期間を設定してください。');
      return false;
    }

    // 予測精度閾値チェック
    if (isNaN(accuracyThreshold) || accuracyThreshold < 0 || accuracyThreshold > 100) {
      showError('予測精度閾値は0%から100%の範囲で設定してください。');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    if (!validateForm()) return;

    const executeBtn = container.querySelector('#btn-execute-prediction');
    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';
    progressContainer.classList.remove('hidden');

    try {
      // 進捗シミュレーション
      updateProgress(10, 'データ収集を開始しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(30, '学習データを準備しています...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(50, 'AIモデルを実行しています...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(80, '予測結果を計算しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      // 需要予測結果を保存
      const predictionData = {
        店舗ID: storeSelect.value,
        商品ID: 'dummy-product-id', // 実際は選択されたカテゴリの商品を処理
        予測対象日: container.querySelector('#prediction-start-date').value,
        予測数量: Math.floor(Math.random() * 100) + 50,
        予測精度: Math.floor(Math.random() * 30) + 70,
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI需要予測処理により自動生成'
      };

      const saved = await window.aivicApi.save(9, predictionData); // 需要予測結果テーブル

      updateProgress(100, '予測処理が完了しました。');

      if (saved) {
        showSuccess('AI需要予測処理が正常に完了しました。需要予測管理画面で結果を確認できます。');
      } else {
        showError('予測結果の保存に失敗しました。');
      }

    } catch (error) {
      showError('予測処理中にエラーが発生しました: ' + error.message);
    } finally {
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
      setTimeout(() => {
        progressContainer.classList.add('hidden');
      }, 2000);
    }
  }

  // 天候データ取込
  async function importWeatherData() {
    try {
      updateProgress(0, '天候データを取得しています...');
      progressContainer.classList.remove('hidden');

      // 天候データのサンプル作成
      const weatherData = {
        店舗ID: storeSelect.value || 'sample-store-id',
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 15,
        平均気温: 20,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '実績値',
        データソース: '気象庁API'
      };

      updateProgress(50, '天候データを処理しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      const saved = await window.aivicApi.save(4, weatherData); // 天候データテーブル

      updateProgress(100, '天候データ取込が完了しました。');

      if (saved) {
        showSuccess('天候データの取込が正常に完了しました。');
      } else {
        showError('天候データの取込に失敗しました。外部APIとの接続を確認してください。');
      }
    } catch (error) {
      showError('天候データの取込に失敗しました: ' + error.message);
    } finally {
      setTimeout(() => {
        progressContainer.classList.add('hidden');
      }, 2000);
    }
  }

  // イベントデータ取込
  async function importEventData() {
    try {
      updateProgress(0, 'イベントデータを取得しています...');
      progressContainer.classList.remove('hidden');

      // イベントデータのサンプル作成
      const eventData = {
        店舗ID: storeSelect.value || 'sample-store-id',
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 100,
        備考: 'AI需要予測用サンプルデータ',
        有効フラグ: true,
        作成者: 'システム',
        更新者: 'システム'
      };

      updateProgress(50, 'イベントデータを処理しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      const saved = await window.aivicApi.save(5, eventData); // イベントデータテーブル

      updateProgress(100, 'イベントデータ取込が完了しました。');

      if (saved) {
        showSuccess('イベントデータの取込が正常に完了しました。');
      } else {
        showError('イベントデータの取込に失敗しました。ファイル形式または必須項目を確認してください。');
      }
    } catch (error) {
      showError('イベントデータの取込に失敗しました: ' + error.message);
    } finally {
      setTimeout(() => {
        progressContainer.classList.add('hidden');
      }, 2000);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-weather-import').addEventListener('click', importWeatherData);
  container.querySelector('#btn-event-import').addEventListener('click', importEventData);

  // ナビゲーション
  container.querySelector('#btn-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1778591780173');
  });
  container.querySelector('#btn-prediction-results').addEventListener('click', () => {
    window.showScreen('scr-1778591838939');
  });
  container.querySelector('#btn-order-management').addEventListener('click', () => {
    window.showScreen('scr-1778591852463');
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}
